  dashLine(g, gx0, yR, xL + span * 0.12, yR, lw);
  dashLine(g, gx0, yT, xPeak - span * 0.04, yT, lw);
  dashLine(g, xG2 - span * 0.09, yR, xG2 + span * 0.05, yR, lw);
  dashLine(g, xG2 - span * 0.09, yP, xL + span * 0.845, yP, lw);
