  var curve = g.polyline(pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
    .fill('none').stroke({ color: MAG, width: Math.max(2, fs * 0.22), linecap: 'round', linejoin: 'round' });

  /* measurement arrows */
  var mA = measure(g, xG1, yR, yT, '\u0394G\u2021', cA, 'end', fs, lw,
