var W = 960, H = 800;
draw.viewbox(0, 0, W, H);

var MAG = '#e6187f', FIELD = '#dcecf8', AXIS = '#9aa4ac', INK = '#111';
var ACC1 = '#d8641a', ACC2 = '#0f7f8c';
var BIGWIN = [-105, 145];

var PRESETS = {
  a: { barrier: 30, dG: -60, win: [-127, 123], name: '(a) Fast, exergonic', tip: '(a) Low barrier + product far below reactants \u2192 fast and strongly exergonic' },
  b: { barrier: 100, dG: -30, win: [-85, 140], name: '(b) Slow, exergonic', tip: '(b) Tall barrier + product below reactants \u2192 slow but still exergonic' },
  c: { barrier: 18, dG: 8, win: [-45, 60], name: '(c) Fast, endergonic', tip: '(c) Shallow hump + product slightly above reactants \u2192 fast but endergonic' },
  d: { barrier: 115, dG: 30, win: [-16, 130], name: '(d) Slow, endergonic', tip: '(d) Very tall barrier + product above reactants \u2192 slow and endergonic' }
};

