  var big = !!cfg.big;
  var win = cfg.win;
  var fs = Math.min(Math.min(w, h) * 0.042, 23);
  var lw = Math.max(0.9, fs * 0.085);
  var fx = x + w * 0.175, fy = y + h * 0.05, fw = w * 0.79, fh = h * 0.75;

  function yOf(E) { return fy + fh * ((win[1] - E) / (win[1] - win[0])); }

  g.rect(fw, fh).move(fx, fy).fill(FIELD);
  g.line(fx, fy, fx, fy + fh).stroke({ color: AXIS, width: lw });
  g.line(fx, fy + fh, fx + fw, fy + fh).stroke({ color: AXIS, width: lw });

  energyArrow(g, x + w * 0.075, y + h * 0.07, fy + fh, Math.min(w * 0.055, 28), fs);

  if (cfg.letter) {
    var lt = txt(g, cfg.letter, { size: fs * (big ? 0.95 : 1.05), weight: 'bold', family: 'Helvetica, Arial, sans-serif' });
    place(lt, x + w * 0.012, y + h * 0.028, 'start', 'middle');
  }

  /* caption + magenta arrow */
  var capY = fy + fh + h * 0.098;
  place(txt(g, 'Reaction progress', { size: fs * 1.02 }), fx + fw * 0.04, capY, 'start', 'middle');
  var a0 = fx + fw * 0.60, a1 = fx + fw * 0.97;
  g.line(a0, capY, a1 - fs * 0.6, capY).stroke({ color: MAG, width: lw * 1.8, linecap: 'round' });
  g.polygon(a1 + ',' + capY + ' ' + (a1 - fs * 0.85) + ',' + (capY - fs * 0.36) + ' ' + (a1 - fs * 0.85) + ',' + (capY + fs * 0.36)).fill(MAG);

  /* geometry */
  var xL = fx + fw * 0.26, xR = fx + fw * 0.80, span = xR - xL;
  var peak = Math.max(cfg.barrier, cfg.dG + 8);
  var E = makeE(cfg.barrier, cfg.dG);
  var yR = yOf(0), yP = yOf(cfg.dG), yT = yOf(peak);
  var xPeak = xL + span * 0.52;
  var gx0 = fx + fw * 0.05;
  var xG1 = fx + fw * 0.19;
  var rightMode = cfg.dG > -18;
  var xG2 = rightMode ? (xR + span * 0.09) : (xL + span * 0.66);
  var cA = big ? ACC1 : INK, cB = big ? ACC2 : INK;

  /* dashed guides */
  dashLine(g, gx0, yR, xL + span * 0.05, yR, lw);                 // reactant baseline (left)
  dashLine(g, gx0, yT, xPeak - span * 0.05, yT, lw);              // transition-state level
  if (rightMode) {
    dashLine(g, xR, yP, fx + fw * 0.93, yP, lw);                  // product level extension
    dashLine(g, xG2 - span * 0.11, yR, xG2 + span * 0.11, yR, lw);// reactant level near arrow
  } else {
    dashLine(g, xG2 - span * 0.11, yR, xG2 + span * 0.09, yR, lw);
    dashLine(g, xG2 - span * 0.11, yP, xL + span * 0.845, yP, lw);
    dashLine(g, xR, yP, fx + fw * 0.95, yP, lw);
  }

  /* curve */
  var pts = [];
  for (var i = 0; i <= 280; i++) { var p = i / 280; pts.push([xL + span * p, yOf(E(p))]); }
  var curve = g.polyline(pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
    .fill('none').stroke({ color: MAG, width: Math.max(2.8, fs * 0.30), linecap: 'round', linejoin: 'round' });

  /* measurement arrows */
  var labFs = fs * (big ? 1.0 : 1.06);
  measure(g, xG1, yR, yT, '\u0394G\u2021', cA, 'left', labFs, lw,
    big ? 'Activation barrier \u0394G\u2021' : null,
    'The height of the hump above the reactant level. A taller \u0394G\u2021 means fewer collisions have enough energy to reach the transition state, so the reaction is slower. It says nothing about whether the products are more stable.');
  measure(g, xG2, yR, yP, '\u0394G\u00B0', cB, rightMode ? (Math.abs(yR - yP) < labFs * 1.85 ? 'above' : 'right') : 'right', labFs, lw,
    big ? 'Free-energy change \u0394G\u00B0' : null,
    'The vertical distance from the reactant level to the product level. Negative (products below) = exergonic and favorable at equilibrium; positive (products above) = endergonic and unfavorable. It says nothing about speed.');

  if (big) {
    var dot = g.circle(fs * 0.5).center(xPeak, yT).fill(MAG).stroke({ color: '#fff', width: 1.5 });
