}

/* ---------- render ---------- */
function render() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');
  if (state.view === 'grid') {
    var keys = ['a', 'b', 'c', 'd'];
    for (var i = 0; i < 4; i++) {
      var col = i % 2, row = (i / 2) | 0;
      var cx = col * (W / 2), cy = row * (H / 2);
      var pr = PRESETS[keys[i]];
      drawPanel(cx + 10, cy + 8, W / 2 - 20, H / 2 - 16,
        { barrier: pr.barrier, dG: pr.dG, win: pr.win, letter: '(' + keys[i] + ')' });
      (function (k, X, Y) {
        var hit = draw.rect(W / 2, H / 2).move(X, Y).fill('#fff').opacity(0);
        hit.css('cursor', 'pointer');
        hit.on('mousemove', function (e) { showTooltip(PRESETS[k].tip + ' \u2014 click to enlarge', e); });
        hit.on('mouseleave', function () { hideTooltip(); });
        hit.on('click', function () { hideTooltip(); selectProfile(k, true); });
      })(keys[i], cx, cy);
    }
  } else {
    var name = state.profile === 'custom' ? 'Custom profile' : PRESETS[state.profile].name;
    drawPanel(30, 10, W - 60, H - 20,
      { barrier: state.barrier, dG: state.dG, win: BIGWIN, letter: name, big: true });
  }
  updateVerdictUI();
}

function updateVerdictUI() {
  var el = document.getElementById('verdictBox');
  if (!el) return;
  el.innerHTML =
    '<b style="color:' + ACC1 + '">\u0394G\u2021 = ' + state.barrier + ' kJ/mol</b> \u2192 ' + rateWord(state.barrier) +
    '<br><b style="color:' + ACC2 + '">\u0394G\u00B0 = ' + fmt(state.dG) + ' kJ/mol</b> \u2192 ' + thermoWord(state.dG);
}

/* ---------- controls ---------- */
function syncUI() {
  var b = document.getElementById('barrierHeightInput');
  var d = document.getElementById('productEnergyInput');
  if (b) { b.value = state.barrier; document.getElementById('barrierHeightVal').value = state.barrier; }
  if (d) { d.value = state.dG; document.getElementById('productEnergyVal').value = state.dG; }
  document.getElementById('viewModeInput').checked = (state.view === 'single');
  document.getElementById('profileSelectInput').value = state.profile;
}

function toggle_viewMode(on) { state.view = on ? 'single' : 'grid'; render(); }

function selectProfile(v, forceSingle) {
  state.profile = v;
  if (v !== 'custom') { state.barrier = PRESETS[v].barrier; state.dG = PRESETS[v].dG; }
  if (forceSingle) state.view = 'single';
  syncUI();
  render();
}
function toggle_profileSelect(v) { selectProfile(v, false); }

function goCustom() {
  state.profile = 'custom';
  document.getElementById('profileSelectInput').value = 'custom';
  if (state.view === 'grid') { state.view = 'single'; document.getElementById('viewModeInput').checked = true; }
}
function update_barrierHeight(v) { state.barrier = v; goCustom(); render(); }
function update_productEnergy(v) { state.dG = v; goCustom(); render(); }

