  <input id="barrierHeightInput" type="range" min="10" max="120" step="2" value="30" oninput="document.getElementById('barrierHeightVal').value=this.value;update_barrierHeight(+this.value)">
</label>
<label>Product energy ΔG°: <output id="productEnergyVal">-60</output> kJ/mol
  <input id="productEnergyInput" type="range" min="-80" max="40" step="2" value="-60" oninput="document.getElementById('productEnergyVal').value=this.value;update_productEnergy(+this.value)">
</label>
<span id="verdictBox" style="font-size:11px;line-height:1.5"></span>
<span style="font-size:10px;color:#666;line-height:1.4">Each grid panel is drawn to its own vertical scale, as in the textbook. The enlarged panel uses one fixed scale, so the two sliders move the hump and the product plateau independently. Hover or click the dashed levels and arrows there for explanations; click a grid panel to enlarge it.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 900, H = 720;
draw.viewbox(0, 0, W, H);

var MAG = '#e6187f', FIELD = '#dcecf8', AXIS = '#9aa4ac', INK = '#111';
var ACC1 = '#d8641a', ACC2 = '#0f7f8c';
var BIGWIN = [-100, 140];

var PRESETS = {
  a: { barrier: 30, dG: -60, win: [-118, 108], name: '(a) Fast, exergonic', tip: '(a) Low barrier + product far below reactants \u2192 fast and strongly exergonic' },
  b: { barrier: 100, dG: -30, win: [-147, 80], name: '(b) Slow, exergonic', tip: '(b) Tall barrier + product below reactants \u2192 slow but still exergonic' },
  c: { barrier: 18, dG: 8, win: [-36, 58], name: '(c) Fast, endergonic', tip: '(c) Shallow hump + product slightly above reactants \u2192 fast but endergonic' },
  d: { barrier: 115, dG: 30, win: [-12, 130], name: '(d) Slow, endergonic', tip: '(d) Very tall barrier + product above reactants \u2192 slow and endergonic' }
};

var state = { view: 'grid', profile: 'a', barrier: 30, dG: -60 };

/* ---------- helpers ---------- */
function ss(t) { t = Math.max(0, Math.min(1, t)); return t * t * (3 - 2 * t); }

function makeE(barrier, dG) {
  var peak = Math.max(barrier, dG + 8);
  return function (p) {
    if (p <= 0.12) return 0;
    if (p <= 0.50) return peak * ss((p - 0.12) / 0.38);
    if (p <= 0.86) return peak + (dG - peak) * ss((p - 0.50) / 0.36);
    return dG;
  };
}

function fmt(v) { return (v < 0 ? '\u2212' + Math.abs(v) : '' + v); }
function rateWord(b) { return b <= 40 ? 'fast' : (b <= 80 ? 'moderate' : 'slow'); }
function thermoWord(d) {
  if (d < -5) return 'favorable (exergonic)';
  if (d > 5) return 'unfavorable (endergonic)';
  return 'nearly balanced (\u0394G\u00B0 \u2248 0)';
}

function txt(g, s, opt) {
  opt = opt || {};
  var t = g.text(s);
  t.font({
    family: opt.family || 'Georgia, "Times New Roman", serif',
    size: opt.size || 14,
    weight: opt.weight || 'normal',
    style: opt.style || 'normal',
    anchor: 'middle',
    leading: 1
  });
  t.fill(opt.fill || INK);
  return t;
}

function halo(t, wid) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': wid || 3, 'stroke-linejoin': 'round' });
  return t;
}

function place(t, X, Y, ha, va) {
  var b = t.bbox();
  var cx = ha === 'start' ? X + b.width / 2 : (ha === 'end' ? X - b.width / 2 : X);
  var cy = va === 'top' ? Y + b.height / 2 : (va === 'bottom' ? Y - b.height / 2 : Y);
  t.center(cx, cy);
  return t;
}

function dashLine(g, x1, y, x2, lw) {
  if (x2 - x1 < lw * 3) return null;
  return g.line(x1, y, x2, y).stroke({ color: INK, width: lw, dasharray: (lw * 4.2) + ',' + (lw * 3.4) });
}

function tri(g, x, y, dy, color) {
  var hw = Math.abs(dy) * 0.56;
  g.polygon(x + ',' + y + ' ' + (x - hw) + ',' + (y + dy) + ' ' + (x + hw) + ',' + (y + dy)).fill(color);
}

function hook(el, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(title, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

/* ---------- measurement arrow ----------
   Large gap  -> double-headed arrow INSIDE the interval, label beside it.
   Small gap  -> tails OUTSIDE with heads pointing inward at each dashed level,
                 label sitting between the two levels (textbook convention).   */
function measure(g, x, yA, yB, label, color, side, fs, lw, tipTitle, tipBody) {
  var yTop = Math.min(yA, yB), yBot = Math.max(yA, yB), gap = yBot - yTop;
  var grp = g.group();
  var hs = fs * 0.44;
  var inside = gap >= fs * 2.4;
  var t = txt(grp, label, { size: fs, style: 'italic', fill: color });
  halo(t, Math.max(2.6, fs * 0.32));
  if (inside) {
    grp.line(x, yTop, x, yBot).stroke({ color: color, width: lw });
    tri(grp, x, yTop, hs, color);
    tri(grp, x, yBot, -hs, color);
    if (side === 'left') place(t, x - fs * 0.40, (yTop + yBot) / 2, 'end', 'middle');
    else place(t, x + fs * 0.40, (yTop + yBot) / 2, 'start', 'middle');
  } else {
    var L = fs * 1.35;
    grp.line(x, yTop - L, x, yTop).stroke({ color: color, width: lw });
    tri(grp, x, yTop, -hs, color);
    grp.line(x, yBot, x, yBot + L).stroke({ color: color, width: lw });
    tri(grp, x, yBot, hs, color);
    if (gap >= fs * 0.95) t.center(x, (yTop + yBot) / 2);
    else place(t, x, yTop - L - fs * 0.30, 'middle', 'bottom');
  }
  t.front();
  if (tipTitle) hook(grp, tipTitle, tipBody);
  return grp;
}

/* ---------- energy gradient arrow ---------- */
function energyArrow(g, cx, top, bottom, hw, fs) {
  var sw = hw * 0.44, hh = hw * 1.45;
  var pts = [[cx, top], [cx + hw, top + hh], [cx + sw, top + hh], [cx + sw, bottom],
  [cx - sw, bottom], [cx - sw, top + hh], [cx - hw, top + hh]];
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#df5227'); add.stop(0.32, '#ef8d47');
    add.stop(0.72, '#fbe08c'); add.stop(1, '#fdf7cd');
  });
  grad.from(0, 0).to(0, 1);
  g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(grad).stroke({ color: '#b2591f', width: 0.8, linejoin: 'round' });
  var t = txt(g, 'Energy', { size: fs * 0.95, weight: 'bold', family: 'Helvetica, Arial, sans-serif' });
  t.center(cx, (top + hh + bottom) / 2);
  t.rotate(-90);
}

/* ---------- badges ---------- */
function badge(g, x, y, s, color, fs) {
  var t = txt(g, s, { size: fs, fill: '#1a1a1a' });
  var b = t.bbox();
  var px = fs * 0.55, py = fs * 0.32;
  g.rect(b.width + 2 * px, b.height + 2 * py).move(x, y).radius(fs * 0.4)
    .fill('#ffffff').opacity(0.94).stroke({ color: color, width: 1.5 });
  t.center(x + px + b.width / 2, y + py + b.height / 2);
  t.front();
  return b.height + 2 * py;
}

/* ---------- one panel ---------- */
function drawPanel(x, y, w, h, cfg) {
  var g = draw.group();
  var big = !!cfg.big;
  var win = cfg.win;
  var base = Math.min(w * 0.92, h);
  var fs = Math.min(base * 0.056, big ? 30 : 24);
  var lw = Math.max(0.95, fs * 0.075);
  var fx = x + w * 0.205, fy = y + h * 0.045, fw = w * 0.765, fh = h * 0.755;

  function yOf(E) { return fy + fh * ((win[1] - E) / (win[1] - win[0])); }

  g.rect(fw, fh).move(fx, fy).fill(FIELD);
  g.line(fx, fy, fx, fy + fh).stroke({ color: AXIS, width: lw });
  g.line(fx, fy + fh, fx + fw, fy + fh).stroke({ color: AXIS, width: lw });

  energyArrow(g, x + w * 0.085, y + h * 0.048, fy + fh, Math.min(w * 0.050, 26), fs);

  if (cfg.letter) {
    var lt = txt(g, cfg.letter, { size: fs * (big ? 1.0 : 1.3), weight: 'bold', family: 'Helvetica, Arial, sans-serif' });
    place(lt, x + w * 0.008, y + h * 0.030, 'start', 'middle');
  }

  /* caption + magenta arrow */
  var capY = fy + fh + h * 0.100;
  place(txt(g, 'Reaction progress', { size: fs * 1.05 }), fx + fw * 0.05, capY, 'start', 'middle');
  var a0 = fx + fw * 0.62, a1 = fx + fw * 0.97;
  g.line(a0, capY, a1 - fs * 0.6, capY).stroke({ color: MAG, width: lw * 1.9, linecap: 'round' });
  g.polygon(a1 + ',' + capY + ' ' + (a1 - fs * 0.85) + ',' + (capY - fs * 0.36) + ' ' + (a1 - fs * 0.85) + ',' + (capY + fs * 0.36)).fill(MAG);

  /* geometry */
  var xL = fx + fw * 0.255, xR = fx + fw * 0.825, span = xR - xL;
  var peak = Math.max(cfg.barrier, cfg.dG + 8);
  var E = makeE(cfg.barrier, cfg.dG);
  var yR = yOf(0), yP = yOf(cfg.dG), yT = yOf(peak);
  var xPeak = xL + span * 0.50, xPlatP = xL + span * 0.86;
  var xG1 = xL - fw * 0.085;
  var dashL = xG1 - fw * 0.050;
  var rightMode = cfg.dG > -18;
  var xG2 = rightMode ? (xR + fw * 0.060) : (xPeak + span * 0.03);
  var cA = big ? ACC1 : INK, cB = big ? ACC2 : INK;

  /* dashed guides — cropped, extending only a little past curve/peak */
  dashLine(g, dashL, yT, xPeak - span * 0.015, lw);        // transition-state level
  dashLine(g, dashL, yR, xL + span * 0.07, lw);            // reactant level (left of curve)
  if (rightMode) {
    dashLine(g, xPlatP, yP, xG2 + fw * 0.050, lw);         // product level past curve end
    dashLine(g, xG2 - fw * 0.050, yR, xG2 + fw * 0.050, lw); // short reactant mark at arrow
  } else {
    dashLine(g, xG2 - fw * 0.048, yR, xG2 + fw * 0.048, lw); // short reactant mark at arrow
    dashLine(g, xG2 - fw * 0.040, yP, xPlatP - span * 0.02, lw);
    dashLine(g, xR, yP, xR + fw * 0.095, lw);
  }

  /* curve */
  var pts = [];
  for (var i = 0; i <= 300; i++) { var p = i / 300; pts.push([xL + span * p, yOf(E(p))]); }
  var curve = g.polyline(pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
    .fill('none').stroke({ color: MAG, width: Math.max(2.6, fs * 0.28), linecap: 'round', linejoin: 'round' });

  /* measurement arrows */
  var labFs = fs * (big ? 1.0 : 1.05);
  measure(g, xG1, yR, yT, '\u0394G\u2021', cA, 'left', labFs, lw,
    big ? 'Activation barrier \u0394G\u2021' : null,
    'The height of the hump above the reactant level. A taller \u0394G\u2021 means fewer collisions have enough energy to reach the transition state, so the reaction is slower. It says nothing about whether the products are more stable.');
  measure(g, xG2, yR, yP, '\u0394G\u00B0', cB, 'right', labFs, lw,
    big ? 'Free-energy change \u0394G\u00B0' : null,
    'The vertical distance from the reactant level to the product level. Negative (products below) = exergonic and favorable at equilibrium; positive (products above) = endergonic and unfavorable. It says nothing about speed.');

  if (big) {
    var dot = g.circle(fs * 0.5).center(xPeak, yT).fill(MAG).stroke({ color: '#fff', width: 1.5 });
    var tsY = Math.max(fy + fs * 0.9, yT - fs * 1.15);
    var tl = txt(g, '\u2021 transition state', { size: fs * 0.70, fill: '#7a1049' });
    halo(tl, 3);
    place(tl, xPeak + span * 0.05, tsY, 'start', 'middle');
    hook(dot, 'Transition state (\u2021)', 'The highest-energy point along the reaction coordinate. Its energy above the reactants defines \u0394G\u2021 and therefore the rate.');
    hook(tl, 'Transition state (\u2021)', 'The highest-energy point along the reaction coordinate. Its energy above the reactants defines \u0394G\u2021 and therefore the rate.');

    var hitR = g.line(dashL, yR, xG2 + fw * 0.05, yR).stroke({ color: '#fff', width: fs * 0.65, opacity: 0 });
    hook(hitR, 'Reactant level', 'The starting free energy of the reactants. Both \u0394G\u2021 and \u0394G\u00B0 are measured from this dashed baseline.');
    var hitP = g.line(xG2 - fw * 0.05, yP, xR + fw * 0.09, yP).stroke({ color: '#fff', width: fs * 0.65, opacity: 0 });
    hook(hitP, 'Product level', 'Where the products settle. Below the reactant line the reaction is exergonic; above it, endergonic.');
    hook(curve, 'Energy profile', 'The magenta curve tracks free energy as reactants convert to products: a flat reactant plateau, one rounded maximum (the transition state), then a flat product plateau.');

    var bfs = fs * 0.70;
    var bx = fx + fw * 0.045, by = fy + fh * 0.815;
    var h1 = badge(g, bx, by, 'Rate: \u0394G\u2021 = ' + cfg.barrier + ' kJ/mol \u2192 ' + rateWord(cfg.barrier), ACC1, bfs);
    badge(g, bx, by + h1 + bfs * 0.4, 'Thermodynamics: \u0394G\u00B0 = ' + fmt(cfg.dG) + ' kJ/mol \u2192 ' + thermoWord(cfg.dG), ACC2, bfs);
  }
  return g;
}

/* ---------- render ---------- */
function render() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');
  if (state.view === 'grid') {
    var keys = ['a', 'b', 'c', 'd'];
    for (var i = 0; i < 4; i++) {
      var col = i % 2, row = (i / 2) | 0;
      var cx = col * (W / 2), cy = row * (H / 2);
      var pr = PRESETS[keys[i]];
      drawPanel(cx + 8, cy + 6, W / 2 - 16, H / 2 - 12,
        { barrier: pr.barrier, dG: pr.dG, win: pr.win, letter: '(' + keys[i] + ')' });
      (function (k, X, Y) {
        var hit = draw.rect(W / 2, H / 2).move(X, Y).fill('#fff').opacity(0);
        hit.css('cursor', 'pointer');
        hit.on('mousemove', function (e) { showTooltip(PRESETS[k].tip + ' \u2014 click to enlarge', e); });
        hit.on('mouseleave', function () { hideTooltip(); });
        hit.on('click', function () { hideTooltip(); selectProfile(k, true); });
      })(keys[i], cx, cy);
    }
  } else {
    var name = state.profile === 'custom' ? 'Custom profile' : PRESETS[state.profile].name;
    drawPanel(20, 10, W - 40, H - 20,
      { barrier: state.barrier, dG: state.dG, win: BIGWIN, letter: name, big: true });
  }
  updateVerdictUI();
}

function updateVerdictUI() {
  var el = document.getElementById('verdictBox');
  if (!el) return;
  el.innerHTML =
    '<b style="color:' + ACC1 + '">\u0394G\u2021 = ' + state.barrier + ' kJ/mol</b> \u2192 ' + rateWord(state.barrier) +
    '<br><b style="color:' + ACC2 + '">\u0394G\u00B0 = ' + fmt(state.dG) + ' kJ/mol</b> \u2192 ' + thermoWord(state.dG);
}

/* ---------- controls ---------- */
function syncUI() {
  var b = document.getElementById('barrierHeightInput');
  var d = document.getElementById('productEnergyInput');
  if (b) { b.value = state.barrier; document.getElementById('barrierHeightVal').value = state.barrier; }
  if (d) { d.value = state.dG; document.getElementById('productEnergyVal').value = state.dG; }
  document.getElementById('viewModeInput').checked = (state.view === 'single');
  document.getElementById('profileSelectInput').value = state.profile;
}

function toggle_viewMode(on) { state.view = on ? 'single' : 'grid'; render(); }

function selectProfile(v, forceSingle) {
  state.profile = v;
  if (v !== 'custom') { state.barrier = PRESETS[v].barrier; state.dG = PRESETS[v].dG; }
  if (forceSingle) state.view = 'single';
  syncUI();
  render();
}
function toggle_profileSelect(v) { selectProfile(v, false); }

function goCustom() {
  state.profile = 'custom';
  document.getElementById('profileSelectInput').value = 'custom';
  if (state.view === 'grid') { state.view = 'single'; document.getElementById('viewModeInput').checked = true; }
}
function update_barrierHeight(v) { state.barrier = v; goCustom(); render(); }
function update_productEnergy(v) { state.dG = v; goCustom(); render(); }

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'Four reactions, four profiles',
    narration: 'All four panels share the same curve shape: a flat reactant plateau, one rounded transition state, a flat product plateau. Only two things differ \u2014 how tall the hump is, and where the products land relative to the reactants.',
    state: { view: 'grid', profile: 'a' }
  },
  {
    title: '(a) Low barrier, downhill',
    narration: 'Zooming into panel (a): a small \u0394G\u2021 means molecules clear the barrier easily, so the reaction is fast, and the product level sits well below the reactants, so it is strongly exergonic.',
    state: { view: 'single', profile: 'a', barrier: 30, dG: -60 }
  },
  {
    title: '(b) Tall barrier, still downhill',
    narration: 'Panel (b) is also exergonic, yet the barrier is much taller. A favorable \u0394G\u00B0 does not guarantee a fast reaction \u2014 this one crawls.',
    state: { view: 'single', profile: 'b', barrier: 100, dG: -30 }
  },
  {
    title: '(c) Low barrier, slightly uphill',
    narration: 'Panel (c) has only a shallow hump, so the reaction is fast, but the products end up a little above the reactants: fast and endergonic, favoring reactants at equilibrium.',
    state: { view: 'single', profile: 'c', barrier: 18, dG: 8 }
  },
  {
    title: '(d) Tall barrier, uphill',
    narration: 'Panel (d) is the worst of both: a very tall \u0394G\u2021 makes it slow, and a positive \u0394G\u00B0 makes it unfavorable.',
    state: { view: 'single', profile: 'd', barrier: 115, dG: 30 }
  },
  {
    title: 'Dial them independently',
    narration: 'Now drag the two sliders. Hold \u0394G\u00B0 fixed and raise the barrier: only the speed verdict changes. Hold the barrier fixed and drag the product level through zero: only the favorability verdict flips. Two separate knobs.',
    state: { view: 'single', profile: 'custom', barrier: 55, dG: -20 }
  }
];
var curStep = 0;

function applyStep(i) {
  curStep = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.state;
  state.view = st.view;
  state.profile = st.profile;
